import OpenAI from "openai";
import { PROVIDERS } from "../config/models.js";

const client = new OpenAI({
  apiKey: process.env.REQUESTY_API_KEY,
  baseURL: PROVIDERS.requesty.baseURL
});

export async function callRequesty(modelId, messages, options = {}) {
  const response = await client.chat.completions.create({
    model: modelId,
    messages,
    temperature: options.temperature ?? 0.7,
    max_tokens: options.max_tokens ?? 8192,
    stream: false,
    ...options
  });

  return {
    content: response.choices[0].message.content,
    usage: response.usage,
    model: response.model,
    finish_reason: response.choices[0].finish_reason
  };
}

export async function callRequestyStream(modelId, messages, onChunk, options = {}) {
  const stream = await client.chat.completions.create({
    model: modelId,
    messages,
    temperature: options.temperature ?? 0.7,
    max_tokens: options.max_tokens ?? 8192,
    stream: true,
    ...options
  });

  let fullContent = "";
  for await (const chunk of stream) {
    const delta = chunk.choices[0]?.delta?.content || "";
    fullContent += delta;
    if (delta && onChunk) onChunk(delta);
  }

  return { content: fullContent };
}
