import fetch from "node-fetch";

export async function callMinimax(modelId, messages, options = {}) {
  const body = {
    model: modelId,
    messages,
    temperature: options.temperature ?? 0.7,
    max_tokens: options.max_tokens ?? 8192,
    stream: false
  };

  const response = await fetch(
    ``,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${process.env.MINIMAX_API_KEY}`,
        "GroupId": process.env.MINIMAX_GROUP_ID
      },
      body: JSON.stringify(body)
    }
  );

  if (!response.ok) {
    const errText = await response.text();
    throw new Error(`MiniMax API error ${response.status}: ${errText}`);
  }

  const data = await response.json();
  return {
    content: data.choices[0].message.content,
    usage: data.usage,
    model: data.model,
    finish_reason: data.choices[0].finish_reason
  };
}

export async function callMinimaxStream(modelId, messages, onChunk, options = {}) {
  const body = {
    model: modelId,
    messages,
    temperature: options.temperature ?? 0.7,
    max_tokens: options.max_tokens ?? 8192,
    stream: true
  };

  const response = await fetch(
    ``,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${process.env.MINIMAX_API_KEY}`,
        "GroupId": process.env.MINIMAX_GROUP_ID
      },
      body: JSON.stringify(body)
    }
  );

  if (!response.ok) {
    const errText = await response.text();
    throw new Error(`MiniMax stream error ${response.status}: ${errText}`);
  }

  let fullContent = "";
  const reader = response.body;

  for await (const rawChunk of reader) {
    const lines = rawChunk.toString("utf8").split("\n").filter(l => l.startsWith("data:"));
    for (const line of lines) {
      const jsonStr = line.replace(/^data:\s*/, "").trim();
      if (jsonStr === "[DONE]") continue;
      try {
        const parsed = JSON.parse(jsonStr);
        const delta = parsed.choices?.[0]?.delta?.content || "";
        fullContent += delta;
        if (delta && onChunk) onChunk(delta);
      } catch {}
    }
  }

  return { content: fullContent };
}
