import { callCerebras, callCerebrasStream } from "./cerebras.js";
import { callRequesty, callRequestyStream } from "./requesty.js";
import { callMinimax, callMinimaxStream } from "./minimax.js";
import { PROVIDERS, MODELS } from "../config/models.js";

function resolveProvider(modelKey) {
  const model = MODELS[modelKey];
  if (!model) throw new Error(`Unknown model key: ${modelKey}`);
  return { model, provider: model.provider };
}

export async function callModel(modelKey, messages, options = {}) {
  const { model, provider } = resolveProvider(modelKey);

  if (provider === "cerebras") {
    return callCerebras(model.modelId, messages, options);
  }
  if (provider === "requesty") {
    return callRequesty(model.modelId, messages, options);
  }
  if (provider === "minimax") {
    return callMinimax(model.modelId, messages, options);
  }
  throw new Error(`Unknown provider: ${provider}`);
}

export async function callModelStream(modelKey, messages, onChunk, options = {}) {
  const { model, provider } = resolveProvider(modelKey);

  if (provider === "cerebras") {
    return callCerebrasStream(model.modelId, messages, onChunk, options);
  }
  if (provider === "requesty") {
    return callRequestyStream(model.modelId, messages, onChunk, options);
  }
  if (provider === "minimax") {
    return callMinimaxStream(model.modelId, messages, onChunk, options);
  }
  throw new Error(`Unknown provider: ${provider}`);
}
