import { callModel } from "../services/modelRouter.js";
import { SYSTEM_PROMPTS } from "../config/prompts.js";

export async function runIntakeOrchestrator(userMessage, conversationHistory = []) {
  const messages = [
    { role: "system", content: SYSTEM_PROMPTS.INTAKE_ORCHESTRATOR },
    ...conversationHistory,
    { role: "user", content: userMessage }
  ];

  const result = await callModel("INTAKE_ORCHESTRATOR", messages, {
    temperature: 0.3,
    max_tokens: 2048
  });

  let parsed;
  try {
    const jsonMatch = result.content.match(/\{[\s\S]*\}/);
    if (!jsonMatch) throw new Error("No JSON found in intake response");
    parsed = JSON.parse(jsonMatch[0]);
  } catch (err) {
    throw new Error(`Intake orchestrator failed to return valid JSON: ${err.message}\nRaw: ${result.content}`);
  }

  if (!parsed.mode || !["autonomous_programming", "chat_council"].includes(parsed.mode)) {
    throw new Error(`Invalid mode returned by intake orchestrator: ${parsed.mode}`);
  }

  return {
    mode: parsed.mode,
    task_summary: parsed.task_summary,
    requirements: parsed.requirements || [],
    constraints: parsed.constraints || [],
    context: parsed.context || "",
    complexity: parsed.complexity || "medium",
    subtasks: parsed.subtasks || [],
    raw_response: result.content,
    usage: result.usage
  };
}
