import { callModel } from "../services/modelRouter.js";
import { SYSTEM_PROMPTS } from "../config/prompts.js";
import { runWorkerSwarm } from "./workers/swarm.js";

export async function runAutonomousOrchestrator(intakeResult, originalMessage) {
  const planningMessages = [
    { role: "system", content: SYSTEM_PROMPTS.AUTONOMOUS_ORCHESTRATOR },
    {
      role: "user",
      content: `Original request: ${originalMessage}\n\nTask specification from intake:\n${JSON.stringify(intakeResult, null, 2)}\n\nCreate a detailed worker assignment plan.`
    }
  ];

  const planResult = await callModel("AUTONOMOUS_ORCHESTRATOR", planningMessages, {
    temperature: 0.4,
    max_tokens: 4096
  });

  let plan;
  try {
    const jsonMatch = planResult.content.match(/\{[\s\S]*\}/);
    if (!jsonMatch) throw new Error("No JSON found in orchestrator plan");
    plan = JSON.parse(jsonMatch[0]);
  } catch (err) {
    throw new Error(`Autonomous orchestrator plan parse error: ${err.message}`);
  }

  const swarmResults = await runWorkerSwarm(plan.assignments, intakeResult);

  const synthesisMessages = [
    { role: "system", content: SYSTEM_PROMPTS.AUTONOMOUS_ORCHESTRATOR },
    {
      role: "user",
      content: `Original request: ${originalMessage}\n\nWorker results:\n${JSON.stringify(swarmResults, null, 2)}\n\nSynthesis instructions: ${plan.synthesis_instructions}\n\nProduce the final integrated output.`
    }
  ];

  const finalResult = await callModel("AUTONOMOUS_ORCHESTRATOR", synthesisMessages, {
    temperature: 0.3,
    max_tokens: 8192
  });

  return {
    plan,
    worker_results: swarmResults,
    final_output: finalResult.content,
    usage: finalResult.usage
  };
}
