**src/agents/workers/swarm.js**
```js
import { callModel } from "../../services/modelRouter.js";
import { SYSTEM_PROMPTS } from "../../config/prompts.js";

const WORKER_MODEL_MAP = {
  kimi_k2: "AUTONOMOUS_WORKER_KIMI",
  glm_5: "AUTONOMOUS_WORKER_GLM",
  minimax_m3: "AUTONOMOUS_WORKER_MINIMAX"
};

async function executeWorker(assignment, sharedContext) {
  const modelKey = WORKER_MODEL_MAP[assignment.model] || "AUTONOMOUS_WORKER_KIMI";

  const contextBlock = sharedContext
    ? `\n\nShared context from other workers:\n${JSON.stringify(sharedContext, null, 2)}`
    : "";

  const messages = [
    { role: "system", content: SYSTEM_PROMPTS.AUTONOMOUS_WORKER },
    {
      role: "user",
      content: `Task: ${assignment.task}\n\nContext: ${assignment.context}${contextBlock}\n\nExpected output: ${assignment.expected_output}`
    }
  ];

  try {
    const result = await callModel(modelKey, messages, {
      temperature: 0.2,
      max_tokens: 8192
    });

    return {
      worker_id: assignment.worker_id,
      model: assignment.model,
      status: "success",
      output: result.content,
      usage: result.usage
    };
  } catch (err) {
    return {
      worker_id: assignment.worker_id,
      model: assignment.model,
      status: "error",
      error: err.message,
      output: null
    };
  }
}

export async function runWorkerSwarm(assignments, intakeResult) {
  const sortedAssignments = [...assignments].sort((a, b) => (a.priority || 0) - (b.priority || 0));

  const priorityGroups = new Map();
  for (const assignment of sortedAssignments) {
    const p = assignment.priority || 1;
    if (!priorityGroups.has(p)) priorityGroups.set(p, []);
    priorityGroups.get(p).push(assignment);
  }

  const allResults = [];
  const completedContext = {};

  const sortedPriorities = [...priorityGroups.keys()].sort((a, b) => a - b);

  for (const priority of sortedPriorities) {
    const group = priorityGroups.get(priority);

    const groupResults = await Promise.all(
      group.map(assignment => executeWorker(assignment, completedContext))
    );

    for (const result of groupResults) {
      if (result.status === "success") {
        completedContext[result.worker_id] = result.output;
      }
      allResults.push(result);
    }
  }

  return allResults;
}
