import { callModel, callModelStream } from "../../services/modelRouter.js";
import { SYSTEM_PROMPTS } from "../../config/prompts.js";

const COUNCIL_MEMBERS = [
  { key: "COUNCIL_MIMO", name: "Mimo 2.5 Pro" },
  { key: "COUNCIL_GLM", name: "GLM 5.2" },
  { key: "COUNCIL_DEEPSEEK", name: "DeepSeek 4 Pro" },
  { key: "COUNCIL_GEMINI", name: "Gemini 3.1" }
];

async function callCouncilMember(memberConfig, userMessage, conversationHistory) {
  const messages = [
    { role: "system", content: SYSTEM_PROMPTS.COUNCIL_MEMBER },
    ...conversationHistory,
    { role: "user", content: userMessage }
  ];

  try {
    const result = await callModel(memberConfig.key, messages, {
      temperature: 0.8,
      max_tokens: 4096
    });

    return {
      member: memberConfig.name,
      model_key: memberConfig.key,
      status: "success",
      response: result.content,
      usage: result.usage
    };
  } catch (err) {
    return {
      member: memberConfig.name,
      model_key: memberConfig.key,
      status: "error",
      error: err.message,
      response: null
    };
  }
}

async function runSynthesizer(councilResponses, userMessage) {
  const responseSummary = councilResponses
    .filter(r => r.status === "success")
    .map(r => `=== ${r.member} ===\n${r.response}`)
    .join("\n\n");

  const messages = [
    { role: "system", content: SYSTEM_PROMPTS.COUNCIL_SYNTHESIZER },
    {
      role: "user",
      content: `Original question: ${userMessage}\n\nCouncil responses:\n\n${responseSummary}\n\nSynthesize these perspectives into a unified, actionable response.`
    }
  ];

  const result = await callModel("COUNCIL_SYNTHESIZER", messages, {
    temperature: 0.5,
    max_tokens: 8192
  });

  return {
    synthesizer: "GLM 5.2",
    synthesis: result.content,
    usage: result.usage
  };
}

export async function runCouncil(userMessage, conversationHistory = []) {
  const memberResults = await Promise.all(
    COUNCIL_MEMBERS.map(member =>
      callCouncilMember(member, userMessage, conversationHistory)
    )
  );

  const successCount = memberResults.filter(r => r.status === "success").length;
  if (successCount === 0) {
    throw new Error("All council members failed to respond.");
  }

  const synthesis = await runSynthesizer(memberResults, userMessage);

  return {
    council_responses: memberResults,
    synthesis,
    member_count: COUNCIL_MEMBERS.length,
    successful_members: successCount
  };
}
