import { v4 as uuidv4 } from "uuid";

const sessions = new Map();

export function createSession() {
  const id = uuidv4();
  sessions.set(id, {
    id,
    created_at: new Date().toISOString(),
    messages: [],
    mode: null,
    metadata: {}
  });
  return id;
}

export function getSession(id) {
  return sessions.get(id) || null;
}

export function addMessageToSession(sessionId, role, content, metadata = {}) {
  const session = sessions.get(sessionId);
  if (!session) throw new Error(`Session ${sessionId} not found`);
  session.messages.push({ role, content, timestamp: new Date().toISOString(), ...metadata });
}

export function setSessionMode(sessionId, mode) {
  const session = sessions.get(sessionId);
  if (!session) throw new Error(`Session ${sessionId} not found`);
  session.mode = mode;
}

export function getConversationHistory(sessionId, maxMessages = 20) {
  const session = sessions.get(sessionId);
  if (!session) return [];
  return session.messages
    .filter(m => m.role === "user" || m.role === "assistant")
    .slice(-maxMessages)
    .map(({ role, content }) => ({ role, content }));
}

export function deleteSession(sessionId) {
  return sessions.delete(sessionId);
}

export function listSessions() {
  return [...sessions.values()].map(({ id, created_at, mode, messages }) => ({
    id,
    created_at,
    mode,
    message_count: messages.length
  }));
}
