**src/routes/chat.js**
```js
import { Router } from "express";
import { runIntakeOrchestrator } from "../agents/intakeOrchestrator.js";
import { runAutonomousOrchestrator } from "../agents/autonomousOrchestrator.js";
import { runCouncil } from "../agents/council/council.js";
import {
  createSession,
  getSession,
  addMessageToSession,
  setSessionMode,
  getConversationHistory
} from "../utils/sessionStore.js";
import { validateRequest, ChatRequestSchema } from "../utils/validator.js";
import { logger } from "../utils/logger.js";

const router = Router();

router.post("/", async (req, res) => {
  let validated;
  try {
    validated = validateRequest(ChatRequestSchema, req.body);
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }

  const { message, session_id, force_mode } = validated;

  let sessionId = session_id;
  if (!sessionId) {
    sessionId = createSession();
  } else {
    const existing = getSession(sessionId);
    if (!existing) {
      return res.status(404).json({ error: `Session ${sessionId} not found` });
    }
  }

  addMessageToSession(sessionId, "user", message);
  const history = getConversationHistory(sessionId, 20);

  logger.info("Chat request received", { sessionId, messageLength: message.length });

  try {
    const intake = await runIntakeOrchestrator(message, history.slice(0, -1));
    const mode = force_mode || intake.mode;
    setSessionMode(sessionId, mode);

    logger.info("Intake classified", { sessionId, mode, complexity: intake.complexity });

    let result;
    let assistantMessage;

    if (mode === "autonomous_programming") {
      result = await runAutonomousOrchestrator(intake, message);
      assistantMessage = result.final_output;

      addMessageToSession(sessionId, "assistant", assistantMessage, {
        mode,
        worker_count: result.worker_results?.length
      });

      return res.json({
        session_id: sessionId,
        mode,
        intake_summary: intake.task_summary,
        response: assistantMessage,
        worker_results: result.worker_results,
        plan: result.plan
      });
    }

    if (mode === "chat_council") {
      result = await runCouncil(message, history.slice(0, -1));
      assistantMessage = result.synthesis.synthesis;

      addMessageToSession(sessionId, "assistant", assistantMessage, {
        mode,
        council_members: result.member_count
      });

      return res.json({
        session_id: sessionId,
        mode,
        intake_summary: intake.task_summary,
        response: assistantMessage,
        council_responses: result.council_responses,
        synthesis: result.synthesis
      });
    }

    return res.status(500).json({ error: `Unknown mode: ${mode}` });
  } catch (err) {
    logger.error("Chat processing error", { sessionId, error: err.message, stack: err.stack });
    return res.status(500).json({ error: err.message });
  }
});

export default router;
```

